// Lane-local repair generators. Preserve screen IDs, positions and existing navigation.
var APP;
function all(l){var a=[l];(l.layers||[]).forEach(k=>a=a.concat(all(k)));return a;}
function named(l,n){return all(l).find(k=>k.name===n);}
function texts(l){return all(l).filter(k=>k.type==='Text');}
function replace(l,a,b){texts(l).filter(t=>t.text===a).forEach(t=>t.text=b);}
function clear(l){l.layers.slice().forEach(k=>k.remove());}
function col(p,n,w,g,pad,fill,h){var f=H.frame({parent:p,name:n,dir:'col',w:w,h:h,gap:g===undefined?16:g,pad:pad||0,fill:fill?H.sw(APP,fill):null});f.stackLayout.alignItems=0;return f;}
function row(p,n,w,g,pad,fill,h){return H.frame({parent:p,name:n,dir:'row',w:w,h:h,gap:g===undefined?8:g,pad:pad||0,fill:fill?H.sw(APP,fill):null});}
function tx(p,t,size,role,w,weight){return H.text({parent:p,text:t,size:size||14,color:H.sw(APP,role||'ink'),w:w,weight:weight||5});}
function space(p,vert){var f=H.frame({parent:p,name:'flex-space',w:1,h:1});f[vert?'verticalSizing':'horizontalSizing']=sketch.FlexSizing.Fill;return f;}
function btn(p,t,id,kind,w,h){var b=row(p,'link:'+id,w,8,{left:12,right:12,top:0,bottom:0},kind==='primary'?'ink':'surface',h||36);b.style.corners.radii=[8,8,8,8];b.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];b.stackLayout.justifyContent=1;tx(b,t,13,kind==='primary'?'inverse':kind==='danger'?'negative':'ink',undefined,6);H.order(b);return b;}
function ib(p,icon,id){var b=row(p,'link:'+id,32,0,0,null,32);b.stackLayout.justifyContent=1;H.icon({parent:b,d:H.paths[icon],size:18,color:H.hex(APP,'secondary')});H.order(b);return b;}
function card(p,n,w,g,pad){var c=col(p,n,w,g===undefined?16:g,pad===undefined?20:pad,'surface');c.style.corners.radii=[12,12,12,12];c.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];return c;}
function mono(p,t,w){return H.text({parent:p,text:t,size:12,mono:true,color:H.sw(APP,'secondary'),w:w});}
function utility(s){all(s).filter(l=>l.name==='link:search'&&l.type==='Group').forEach(b=>{b.style.fills=[{color:H.sw(APP,'surface'),enabled:true}];b.style.borders=[{color:H.sw(APP,'line'),thickness:1,position:sketch.Style.BorderPosition.Inside}];texts(b).forEach(t=>t.style.textColor=H.sw(APP,'ink'));});var f=named(s,'sidebar');var foot=f&&named(f,'link:settings');if(foot){foot.stackLayout.gap=6;foot.stackLayout.apply();}}
function normalized(s){all(s).forEach(l=>{if(/^link:.* \d+$/.test(l.name))l.name=l.name.replace(/ \d+$/,'');});}
function final(s){utility(s);H.relayout(s);normalized(s);H.out({screen:s.name,id:s.id,frame:s.frame,links:all(s).filter(l=>l.name.startsWith('link:')).map(l=>l.name)});}
function edit(id,fn){['Light','Dark'].forEach(a=>{APP=a+'/Clean';var s=H.page('Proto macOS '+a).layers.find(l=>l.name==='Screen/macos/'+APP+'/'+id);if(!s)throw Error('Missing '+id);var x=s.frame.x,y=s.frame.y;fn(s);final(s);s.frame.x=x;s.frame.y=y;});}

var TARGET="settings-about";
edit(TARGET,function(s){var p=named(s,'settings-content');
if(TARGET==='settings-about'){replace(p,'Development build · Version 0.1.0 (prototype)','Version 0.1.0');replace(p,'Version shown is illustrative prototype copy.','© Weave. All rights reserved.');}
if(TARGET==='settings-privacy'){replace(p,'Current session · macOS','15 Sep 2026 · 10:24 SGT · Current session · macOS');replace(p,'This Mac · Trusted device','14 Sep 2026 · 16:08 SGT · This Mac · Trusted device');}
if(TARGET==='settings-voice'){replace(p,'Audio devices','Audio & voice preferences');replace(p,'Live voice','Live voice preference');replace(p,'Allow hands-free conversations.','Saved: On. Unavailable until microphone access is repaired.');replace(p,'Access needs attention on this Mac.','Allow Weave in System Settings → Privacy & Security → Microphone.');replace(p,'Repair','Open System Settings');}
if(TARGET==='settings-devices'){var r=named(p,'row:Full Disk Access');clear(r);r.frame.height=88;var label=col(r,'label',410,6);tx(label,'Full Disk Access · Not granted',13,'ink');tx(label,'System Settings → Privacy & Security → Full Disk Access. Enable Weave, then reopen it.',12,'secondary',410);H.order(label);space(r);btn(r,'Open System Settings','settings-devices');H.order(r);replace(p,'Revoke or rotate','Enrollment credentials');replace(p,'Manage device enrollment credentials.','Revoke this Mac or rotate its credential separately.');var rr=named(p,'row:Revoke or rotate');var b=rr.layers.find(l=>l.name.startsWith('link:'));clear(b);tx(b,'Revoke device',12,'negative');H.order(b);var children=rr.layers.slice().reverse();var rot=btn(rr,'Rotate credential','settings-devices');children.push(rot);children.forEach((l,i)=>l.index=children.length-1-i);rr.stackLayout.gap=8;var c=named(p,'This Mac');c.layers.filter(l=>l.name.startsWith('row:')&&l!==r).forEach(l=>l.frame.height=60);}
if(TARGET==='settings-billing'||TARGET==='settings-billing--plan'){replace(p,'Choose plan','Change billing interval');var r=named(p,'row:Billing cycle');clear(r);r.frame.height=88;var l=col(r,'label',410,6);tx(l,'Current billing',13);tx(l,'Monthly · US$300. Review interval changes before checkout.',12,'secondary',410);H.order(l);space(r);btn(r,'Review options','settings-billing--plan');H.order(r);all(p).filter(l=>l.type==='SymbolInstance'&&l.name.startsWith('AgentLimitsCard')).forEach(i=>{var c=i.detach();texts(c).filter(t=>t.text==='Context window'||t.text==='+ Context window').forEach(t=>{var b=t.parent;clear(b);b.style.fills=[];b.style.borders=[];tx(b,'Context window',13,'secondary');H.order(b);});});}
if(TARGET==='settings-billing--plan'){var modal=named(s,'Dialog');clear(modal);modal.frame.width=540;modal.stackLayout.gap=16;tx(modal,'Change billing interval',22,'ink',484,7);tx(modal,'Founder · Your active plan',13,'secondary',484);btn(modal,'◉ Monthly · US$300 / month','settings-billing--plan',null,484);btn(modal,'○ Annual · US$3,000 / year','settings-billing--plan',null,484);tx(modal,'Select an interval, then continue to checkout to review the total and confirm. Nothing changes until you confirm there.',13,'secondary',484);var r=row(modal,'checkout-actions',484);btn(r,'Cancel','back');space(r);btn(r,'Continue to checkout','settings-billing','primary');H.order(r);H.order(modal);modal.frame.x=450;modal.frame.y=250;}
});